import React, { useState, useEffect } from 'react';
import axios from 'axios';

const EventForm = ({ onEventCreated, currentUserId }) => {
    const [formData, setFormData] = useState({ name: '', date: '', location: '', description: '' });
    const [searchTerm, setSearchTerm] = useState('');
    const [searchResults, setSearchResults] = useState([]);
    const [selectedUsers, setSelectedUsers] = useState([]);
    const [isSearching, setIsSearching] = useState(false);

    useEffect(() => {
        const delayDebounceFn = setTimeout(async () => {
            if (searchTerm.length >= 2) {
                setIsSearching(true);
                try {
                    const res = await axios.get(`http://localhost:5000/api/auth/users/search?query=${searchTerm}`);

                    // FILTER: Ensure the current logged-in user is NOT in the search results
                    const filtered = res.data.filter(u => String(u._id) !== String(currentUserId));
                    setSearchResults(filtered);
                } catch (err) {
                    console.error("Search error", err);
                } finally {
                    setIsSearching(false);
                }
            } else {
                setSearchResults([]);
            }
        }, 300);
        return () => clearTimeout(delayDebounceFn);
    }, [searchTerm, currentUserId]);

    const handleSelectUser = (user) => {
        if (!selectedUsers.find(u => u._id === user._id)) {
            setSelectedUsers([...selectedUsers, user]);
        }
        setSearchTerm('');
        setSearchResults([]);
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        try {
            const eventData = {
                ...formData,
                attendees: selectedUsers.map(u => u._id),
                creator: currentUserId
            };
            const res = await axios.post('http://localhost:5000/api/events', eventData);
            alert('Event Created Successfully!');
            if (onEventCreated) onEventCreated(res.data);
            setFormData({ name: '', date: '', location: '', description: '' });
            setSelectedUsers([]);
        } catch (err) {
            alert("Error: " + (err.response?.data?.message || "Could not save event"));
        }
    };

    const styles = {
        input: { width: '100%', padding: '12px', marginBottom: '10px', borderRadius: '6px', border: '1px solid #ddd', boxSizing: 'border-box' },
        dropdown: { position: 'absolute', width: '100%', backgroundColor: 'white', border: '1px solid #ccc', borderRadius: '4px', zIndex: 100, boxShadow: '0 4px 10px rgba(0,0,0,0.1)' },
        item: { padding: '10px', cursor: 'pointer', borderBottom: '1px solid #eee', color: '#333' },
        chip: { backgroundColor: '#667eea', color: 'white', padding: '5px 12px', borderRadius: '20px', marginRight: '5px', fontSize: '14px', display: 'inline-block', marginBottom: '5px' },
        btn: { width: '100%', padding: '12px', backgroundColor: '#667eea', color: 'white', border: 'none', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold' }
    };

    return (
        <div style={{ color: '#333' }}>
            <form onSubmit={handleSubmit}>
                <input placeholder="Event Name" value={formData.name} onChange={e => setFormData({ ...formData, name: e.target.value })} required style={styles.input} />
                <input type="date" value={formData.date} onChange={e => setFormData({ ...formData, date: e.target.value })} required style={styles.input} />
                <input placeholder="Location" value={formData.location} onChange={e => setFormData({ ...formData, location: e.target.value })} style={styles.input} />

                <div style={{ position: 'relative' }}>
                    <input placeholder="Invite friends by name or email..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} style={styles.input} />
                    {searchResults.length > 0 && (
                        <div style={styles.dropdown}>
                            {searchResults.map(u => (
                                <div key={u._id} onClick={() => handleSelectUser(u)} style={styles.item}>
                                    {u.name} ({u.email})
                                </div>
                            ))}
                        </div>
                    )}
                </div>

                <div style={{ margin: '10px 0' }}>
                    {selectedUsers.map(u => (
                        <span key={u._id} style={styles.chip}>{u.name} ✕</span>
                    ))}
                </div>

                <button type="submit" style={styles.btn}>Create Event</button>
            </form>
        </div>
    );
};

export default EventForm;
